  // Wake schedule: 16 times per day, roughly every 90 minutes
  // Alternating between :07 and :37 past the hour
  const wakeHours = [0, 1, 3, 4, 6, 7, 9, 10, 12, 13, 15, 16, 18, 19, 21, 22];
  const wakeMinutes = [7, 37]; // alternates

  function getNextWakeTime() {
    const now = new Date();
    const currentHour = now.getUTCHours();
    const currentMinute = now.getUTCMinutes();

    // Build list of all wake times for today
