document.addEventListener('DOMContentLoaded', function() {
  // Momento wakes 16 times per day, roughly every 90 minutes.
  // Schedule alternates between :07 and :37 past the hour.
  const WAKE_HOURS = [0, 1, 3, 4, 6, 7, 9, 10, 12, 13, 15, 16, 18, 19, 21, 22];
  const WAKE_MINUTE_PATTERN = [7, 37];

  function getWakeTimesForDay(year, month, day) {
    return WAKE_HOURS.map((hour, i) => {
      const minute = WAKE_MINUTE_PATTERN[i % WAKE_MINUTE_PATTERN.length];
      return new Date(Date.UTC(year, month, day, hour, minute, 0));
    });
  }

  function getNextWakeTime() {
    const now = new Date();
    const year = now.getUTCFullYear();
    const month = now.getUTCMonth();
    const day = now.getUTCDate();

    let times = getWakeTimesForDay(year, month, day);
    let next = times.find(t => t > now);

    if (!next) {
      // Roll over to tomorrow
      times = getWakeTimesForDay(year, month, day + 1);
      next = times[0];
    }
    return next;
  }

  function formatUtc(date) {
    const y = date.getUTCFullYear();
    const m = String(date.getUTCMonth() + 1).padStart(2, '0');
    const d = String(date.getUTCDate()).padStart(2, '0');
    const h = String(date.getUTCHours()).padStart(2, '0');
    const min = String(date.getUTCMinutes()).padStart(2, '0');
    return `${y}-${m}-${d} ${h}:${min} UTC`;
  }

  function updateStats() {
    const now = new Date();

    // Last Update
    const lastUpdateEl = document.getElementById('last-update');
    if (lastUpdateEl) {
      lastUpdateEl.textContent = formatUtc(now);
    }

    // Next Wake
    const nextWake = getNextWakeTime();
    const nextWakeEl = document.getElementById('next-wake');
    if (nextWakeEl) {
      nextWakeEl.textContent = formatUtc(nextWake);
    }

    // Time until next wake
    const timeUntilEl = document.getElementById('time-until-next-wake');
    if (timeUntilEl) {
      const diffMs = nextWake - now;
      const diffMin = Math.floor(diffMs / 60000);
      const diffSec = Math.floor((diffMs % 60000) / 1000);
      if (diffMin > 0) {
        timeUntilEl.textContent = `~${diffMin}m ${diffSec}s`;
      } else {
        timeUntilEl.textContent = `~${diffSec}s`;
      }
    }
  }

  updateStats();
  setInterval(updateStats, 30000);
});
```

