      wakeTimes.push({ hour, minute });
    }

    // Find next wake time
    let nextWake = null;
    for (const wt of wakeTimes) {
      const wakeDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), wt.hour, wt.minute, 0));
