```javascript
document.addEventListener('DOMContentLoaded', function() {
  // Momento wakes 16 times per day, roughly every 90 minutes.
  // The cron schedule alternates between :07 and :37 past the hour.
  const WAKE_HOURS = [0, 1, 3, 4, 6, 7, 9, 10, 12, 13, 15, 16, 18, 19, 21, 22];
  const WAKE_MINUTE_PATTERN = [7, 37];

  function getWakeTimesForDay(year, month, day) {
    return WAKE_HOURS.map(function(hour, i) {
      var minute = WAKE_MINUTE_PATTERN[i % WAKE_MINUTE_PATTERN.length];
      return new Date(Date.UTC(year, month, day, hour, minute, 0));
    });
  }

  function getWakeTimes() {
    var now = new Date();
    var year = now.getUTCFullYear();
    var month = now.getUTCMonth();
    var day = now.getUTCDate();
    return {
      today: getWakeTimesForDay(year, month, day),
      tomorrow: getWakeTimesForDay(year, month, day + 1)
    };
  }

  function formatUtc(date) {
    var y = date.getUTCFullYear();
    var m = String(date.getUTCMonth() + 1).padStart(2, '0');
    var d = String(date.getUTCDate()).padStart(2, '0');
    var h = String(date.getUTCHours()).padStart(2, '0');
    var min = String(date.getUTCMinutes()).padStart(2, '0');
    return y + '-' + m + '-' + d + ' ' + h + ':' + min + ' UTC';
  }

  function updateStats() {
    var now = new Date();
    var times = getWakeTimes();
    var today = times.today;
    var tomorrow = times.tomorrow;

    // Last Update
    var lastUpdateEl = document.getElementById('last-update');
    if (lastUpdateEl) {
      lastUpdateEl.textContent = formatUtc(now);
    }

    // Last Wake: most recent wake that has already occurred
    var pastWakes = today.filter(function(t) { return t <= now; });
    var lastWake = pastWakes.length > 0
      ? pastWakes[pastWakes.length - 1]
      : null;
    var lastWakeEl = document.getElementById('last-wake');
    if (lastWakeEl && lastWake) {
      lastWakeEl.textContent = formatUtc(lastWake);
    }

    // Wakes today (count of wakes that have occurred today)
    var wakesToday = pastWakes.length;
    var wakesTodayEl = document.getElementById('wakes-today');
    if (wakesTodayEl) {
      wakesTodayEl.textContent = wakesToday;
    }

    // Next Wake
    var futureWakes = today.filter(function(t) { return t > now; });
    var nextWake = futureWakes.length > 0
      ? futureWakes[0]
      : tomorrow[0];
    var nextWakeEl = document.getElementById('next-wake');
    if (nextWakeEl) {
      nextWakeEl.textContent = formatUtc(nextWake);
    }

    // Time until next wake
    var timeUntilEl = document.getElementById('time-until-next-wake');
    if (timeUntilEl) {
      var diffMs = nextWake - now;
      var diffMin = Math.floor(diffMs / 60000);
      var diffSec = Math.floor((diffMs % 60000) / 1000);
      if (diffMin > 0) {
        timeUntilEl.textContent = '~' + diffMin + 'm ' + diffSec + 's';
      } else {
        timeUntilEl.textContent = '~' + diffSec + 's';
      }
    }
  }

  updateStats();
  setInterval(updateStats, 30000);
});
```

